#include "native.h"
/* kdialog uses 0/1/2 for yes/no/cancel. Preserve that status separately. */
static int dialog(char *const args[]){pid_t pid=fork();if(pid<0)return 2;if(!pid){execv(args[0],args);_exit(2);}int status;while(waitpid(pid,&status,0)<0)if(errno!=EINTR)return 2;return WIFEXITED(status)?WEXITSTATUS(status):2;}
int main(void){char *text=helper_status("/usr/libexec/w202-gnss-control");if(!text)return 1;struct json j;int power=-1;char *service=NULL;if(jparse(&j,text)){power=jbool(&j,jget(&j,0,"power_requested"));service=jtext(&j,jget(&j,0,"service"));}free(j.v);free(text);char *message=NULL;asprintf(&message,"GNSS：%s\n接收服务：%s\n开启不代表已获得定位。最长接收一小时。",power<0?"接口不可用":power?"已请求开启":"已关闭",service?service:"未知");char *a[]={"/usr/bin/kdialog","--title","GNSS","--yesnocancel",message,"--yes-label","开启 GNSS","--no-label","关闭 GNSS",NULL};int choice=dialog(a),result=0;if(choice==0||choice==1){char *b[]={"/usr/bin/pkexec","/usr/libexec/w202-gnss-control",choice==0?"start":"stop",NULL};result=run_command(b,75,NULL);if(result){char *c[]={"/usr/bin/kdialog","--title","GNSS","--error","GNSS 操作失败或授权已取消。",NULL};dialog(c);}}free(message);free(service);return result?1:0;}
